    /// Each fixture in `payload.invalid-examples.json` MUST be
    /// rejected by at least one of: serde deserialization, or
    /// JSON-Schema validation under the `validate` feature. The
    /// fixture file documents the producer-side bug class that
    /// each payload exemplifies; this generated test pins it.
    #[cfg(feature = "validate")]
    #[test]
    fn rejects_invalid_examples() {
        use crate::validate::ValidatedPayload;
        let fixtures: &[(&str, &str)] = &[
            (
                "No `vetterDid` filter. A lookup by DID would answer \"is this member a vetter?\" for anyone, listed or not — the one question a listing must not answer. An applicant who has a vetter's DID checks eligibility through vetting/request's `eligibilityVp`.",
                "{\n  \"vetterDid\": \"did:webvh:QmCarolScid1:kernel-vtc.example:carol\"\n}",
            ),
            ("`limit` is at least 1.", "{\n  \"limit\": 0\n}"),
            ("`limit` is at most 100.", "{\n  \"limit\": 101\n}"),
            (
                "`cursor` is a non-empty token. An empty string is not the first page — omit the member instead.",
                "{\n  \"cursor\": \"\"\n}",
            ),
            (
                "`language` is a BCP 47 tag, not a language name.",
                "{\n  \"language\": \"German\"\n}",
            ),
            (
                "`country` is an upper-case ISO 3166-1 alpha-2 code, the same form a profile stores.",
                "{\n  \"country\": \"at\"\n}",
            ),
            (
                "`method` comes from the shared VettingMethod vocabulary. `phone` is not a vetting method.",
                "{\n  \"method\": \"phone\"\n}",
            ),
            (
                "`eventFrom` is a `YYYY-MM-DD` date.",
                "{\n  \"eventFrom\": \"next week\"\n}",
            ),
            (
                "`eventTo` is a date, not a date-time; events are matched by UTC date.",
                "{\n  \"eventTo\": \"2026-10-31T23:59:59Z\"\n}",
            ),
            ("`eventName` is non-empty when present.", "{\n  \"eventName\": \"\"\n}"),
            (
                "No `listed` filter. Unlisted profiles are never returned, so there is nothing to select.",
                "{\n  \"listed\": false\n}",
            ),
            (
                "`ext` keys must be reverse-DNS namespaces (SPEC §4.5.1).",
                "{\n  \"ext\": {\n    \"mine\": {}\n  }\n}",
            ),
        ];
        for (i, (note, raw)) in fixtures.iter().enumerate() {
            let value: serde_json::Value = match serde_json::from_str(raw) {
                Ok(v) => v,
                Err(_) => continue,
            };
            let serde_ok = serde_json::from_value::<super::Payload>(value.clone()).is_ok();
            let schema_ok = super::Payload::validate_value(&value).is_ok();
            assert!(
                !(serde_ok && schema_ok),
                "invalid-example #{} ({:?}) was accepted by both serde and JSON Schema; \
                         the fixture's stated failure class is no longer caught:\n{}",
                i + 1,
                note,
                raw
            );
        }
    }
